<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class RefundRepository {
 public static function table_name(): string { global $wpdb; return $wpdb->prefix.'avanik_refunds'; }
 public static function install(): void { global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $t=self::table_name(); $c=$wpdb->get_charset_collate(); dbDelta("CREATE TABLE {$t} (id bigint unsigned NOT NULL AUTO_INCREMENT, refund_id varchar(40) NOT NULL, booking_id varchar(40) NOT NULL, payment_id varchar(40) NOT NULL DEFAULT '', provider_reference varchar(128) NOT NULL DEFAULT '', currency char(3) NOT NULL DEFAULT 'IRR', gross_amount decimal(20,4) NOT NULL DEFAULT 0, provider_fee decimal(20,4) NOT NULL DEFAULT 0, avanik_fee decimal(20,4) NOT NULL DEFAULT 0, agency_adjustment decimal(20,4) NOT NULL DEFAULT 0, customer_refund decimal(20,4) NOT NULL DEFAULT 0, status varchar(24) NOT NULL DEFAULT 'requested', reason varchar(255) NOT NULL DEFAULT '', created_at datetime NOT NULL, updated_at datetime NOT NULL, completed_at datetime DEFAULT NULL, PRIMARY KEY(id), UNIQUE KEY refund_id(refund_id), KEY booking_id(booking_id), KEY status(status)) {$c};"); }
 public static function create(array $d): string|false { global $wpdb; $id='RFD-'.strtoupper(wp_generate_password(12,false,false)); $ok=$wpdb->insert(self::table_name(),['refund_id'=>$id,'booking_id'=>sanitize_text_field($d['booking_id']??''),'payment_id'=>sanitize_text_field($d['payment_id']??''),'provider_reference'=>sanitize_text_field($d['provider_reference']??''),'currency'=>sanitize_text_field($d['currency']??'IRR'),'gross_amount'=>(float)($d['gross_amount']??0),'provider_fee'=>(float)($d['provider_fee']??0),'avanik_fee'=>(float)($d['avanik_fee']??0),'agency_adjustment'=>(float)($d['agency_adjustment']??0),'customer_refund'=>(float)($d['customer_refund']??0),'status'=>sanitize_key($d['status']??'requested'),'reason'=>sanitize_text_field($d['reason']??''),'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')],['%s','%s','%s','%s','%s','%f','%f','%f','%f','%f','%s','%s','%s','%s']); return $ok?$id:false; }
}